	</div>
{/snippet}
{#snippet merchantCell(r: ReceiptRow)}
	{@const preview = notePreview(r.notes)}
	{r.merchant_name ?? ''}
	<!-- A Note reads as part of the merchant ("Costco, Sam's birthday gift"), so it
	     sits under the name rather than in a column of its own — the table has no
	     width to spare, and DataTable is overflow-visible on desktop. Rows without
	     a note render nothing. `title` is a bonus, not the affordance: it fails on
	     touch and keyboard, and clicking the row already opens the full note. -->
	{#if preview}
		<div class="truncate text-xs text-gray-500" title={preview} data-testid="note-preview">
			{preview}
		</div>
	{/if}
{/snippet}
{#snippet amountCell(r: ReceiptRow)}
	{@const dupInfo = getDuplicateInfo(r.id, duplicateGroups)}
	<div class="flex items-center justify-end gap-2">
		{#if r.total_amount == null}
			<!-- Amount OCR could not read: flag rather than show a misleading 0.00 -->
			<span
				class="inline-flex items-center gap-1 rounded-sm bg-yellow-200 px-2 py-0.5 text-xs font-medium text-yellow-800"
				title="Receipt amount could not be read — open the receipt to enter it"
				aria-label="Amount not read"
			>
				⚠ Amount not read
			</span>
		{:else}
			<span
				>{formatCurrencyWithEstimate(
					r.total_amount,
					r.currency,
					r.exchange_rate_to_cad ? r.total_amount * r.exchange_rate_to_cad : null
				)}</span
			>
		{/if}
		{#if dupInfo.isDuplicate}
			<span
				class="inline-flex items-center gap-1 rounded-sm bg-yellow-200 px-2 py-0.5 text-xs font-medium text-yellow-800"
				title="Potential duplicate: {dupInfo.count} receipts with same amount and date"
				aria-label="{dupInfo.count} duplicates"
			>
				<svg
					class="size-3"
					fill="none"
					stroke="currentColor"
					viewBox="0 0 24 24"
					aria-hidden="true"
				>
					<path
						stroke-linecap="round"
						stroke-linejoin="round"
						stroke-width="2"
						d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
					/>
				</svg>
				<span>{dupInfo.count}</span>
			</span>
		{/if}
	</div>
{/snippet}
{#snippet categoryCell(r: ReceiptRow)}
	<CategoryDropdown
		currentCategory={categoryMap[r.id] ?? null}
		{categories}
		{groups}
		merchantName={r.merchant_name ?? ''}
		familyId={familyId ?? ''}
		onCategorySelect={(category) => handleCategorySelect(r.id, category)}
		onCreateNewCategory={handleCreateNewCategory}
		onVendorRuleCreated={handleVendorRuleCreated}
	/>
{/snippet}
{#snippet actionsCell(r: ReceiptRow)}
	<!-- #{#rct6b} Only Delete remains; text-link style matches the other list pages -->
	<button
		class="text-xs text-red-600 hover:underline disabled:opacity-50"
		onclick={() => deleteReceipt(r)}
		disabled={deleting.has(r.id)}
	>
		{deleting.has(r.id) ? 'Deleting…' : 'Delete'}
	</button>
{/snippet}
{#snippet receiptsEmpty()}
	{#if allReceipts.length === 0}
		<!-- #{#ems1a} No data empty state -->
		<div class="flex flex-col items-center gap-3">
			<svg class="size-12 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
				<path
					stroke-linecap="round"
					stroke-linejoin="round"
					stroke-width="2"
					d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
				/>
			</svg>
			<h3 class="text-lg font-medium text-gray-700">No receipts yet</h3>
			<p class="max-w-md text-sm text-gray-600">
				Upload your first receipt to start tracking expenses. You can upload images or PDFs of your
				receipts.
			</p>
		</div>
	{:else if filterNeedsReview}
		<!-- #{#ems1b} Special case: Needs Review filter -->
		<div class="flex flex-col items-center gap-3">
			<svg class="size-10 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
				<path
					stroke-linecap="round"
					stroke-linejoin="round"
					stroke-width="2"
					d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
				/>
			</svg>
			<h3 class="text-lg font-medium text-gray-700">All dates verified!</h3>
			<p class="max-w-md text-sm text-gray-600">
				No receipts need date review. All {allReceipts.length} receipt{allReceipts.length === 1
					? ''
					: 's'} have been verified.
			</p>
			<button
				type="button"
				onclick={() => (filterNeedsReview = false)}
				class="mt-2 rounded-sm border border-gray-300 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50"
			>
				Clear filter
			</button>
		</div>
	{:else}
		<!-- #{#ems1b} Filtered data empty state -->
		<FilteredEmptyState
			count={allReceipts.length}
			itemNoun="receipt"
			onClear={clearClientFilters}
		/>
	{/if}
{/snippet}

<DataTable
	rows={receipts}
	columns={[
		{ key: 'image', header: 'Image', cell: imageCell },
		{ key: 'date', header: 'Date', sortValue: (r) => r.transaction_date ?? '', cell: dateCell },
		{
			key: 'merchant',
			header: 'Merchant',
			sortValue: (r) => r.merchant_name ?? '',
			cell: merchantCell
		},
		{
			key: 'amount',
			header: 'Amount',
			align: 'right',
			sortValue: (r) => r.total_amount ?? 0,
			cell: amountCell
		},
		// interactive: the dropdown owns clicks in this cell, so they must not
		// also open the receipt edit modal.
		{ key: 'category', header: 'Category', interactive: true, cell: categoryCell },
		{ key: 'actions', header: 'Actions', align: 'center', interactive: true, cell: actionsCell }
	]}
	getRowId={(r) => r.id}
	selectable
	bind:selection={receiptSelection}
	onRowClick={openEditModal}
	initialSort={{ key: 'date', direction: 'desc' }}
	rowClass={(r) =>
		receiptSelection.selected.has(r.id)
			? 'border-l-4 border-l-blue-500 bg-blue-50'
			: getDuplicateInfo(r.id, duplicateGroups).isDuplicate
				? 'border-l-4 border-l-yellow-400 bg-yellow-50'
				: ''}
	empty={receiptsEmpty}
/>

