	/**
	 * #{#spl5a} Update the original (reduce amount, set split_group_id, clear match).
	 * On failure, best-effort delete of the just-inserted split keeps the pair consistent.
	 */
	private async reduceOriginalAfterSplitOrRollback(
		receiptId: string,
		remainingAmount: number,
		splitGroupId: string,
		newReceiptId: string
	): Promise<ReceiptRow> {
		const { data: updatedOriginal, error: updateError } = await this.supabase
			.from('receipts')
			.update({
				total_amount: remainingAmount,
				matched_transaction_id: null,
				split_group_id: splitGroupId
			})
			.eq('id', receiptId)
			.select('*')
			.single();

		if (updateError) {
			// Rollback: delete the newly created receipt
			try {
				await this.supabase.from('receipts').delete().eq('id', newReceiptId);
			} catch {
				// Best-effort rollback
			}
			throw updateError;
		}

		return updatedOriginal as ReceiptRow;
	}

	/**
	 * #{#blk3a} Bulk delete multiple receipts in a single database operation
	 * @param receiptIds Array of receipt IDs to delete
	 * @returns Promise that resolves when deletion is complete
	 */
	async bulkDeleteReceipts(receiptIds: string[]): Promise<{ deletedCount: number }> {
		return withRetry(async () => {
			// Get authenticated user
			const user = (await this.supabase.auth.getUser()).data.user;
			if (!user) throw new Error('Not authenticated');

			// Delete all receipts in a single query using IN clause
			// Only delete receipts belonging to the authenticated user
			const { error } = await this.supabase
				.from('receipts')
				.delete()
				.in('id', receiptIds)
				.eq('user_id', user.id);

			if (error) throw error;

			// Return metadata about deletion
			return { deletedCount: receiptIds.length };
		});
	}
}

