import type { ReceiptRow } from '$lib/models/Receipt';

/**
 * Detects duplicate receipts based on matching total_amount and transaction_date.
 *
 * Specifications implemented:
 * - #{#dup1b} Duplicate detection logic
 * - #{#dup3a} Performance optimization
 *
 * @param receipts - Array of receipts to analyze for duplicates
 * @returns Map where keys are composite keys (amount|date) and values are arrays of receipt IDs
 *          Only includes groups with 2+ receipts (actual duplicates)
 */
export function detectDuplicates(receipts: ReceiptRow[]): Map<string, string[]> {
	const groups = new Map<string, string[]>();

	// Single pass through receipts - O(n) complexity
	for (const receipt of receipts) {
		// Skip receipts with null/undefined amount or date (#{#dup1b} requirement)
		if (receipt.total_amount == null || !receipt.transaction_date) {
			continue;
		}

		// Create composite key from amount and date
		const key = `${receipt.total_amount}|${receipt.transaction_date}`;

		// Get existing group or create new array
		const existing = groups.get(key) || [];
		existing.push(receipt.id);
		groups.set(key, existing);
	}

	// Filter out non-duplicates (groups with only 1 receipt)
	const keysToDelete: string[] = [];
	groups.forEach((ids, key) => {
		if (ids.length < 2) {
			keysToDelete.push(key);
		}
	});
	keysToDelete.forEach((key) => groups.delete(key));

	return groups;
}

