=== Expense interface ===
export interface Expense {
	receipt_id: string;
	merchant_name: string;
	total_amount: number | null; // null when OCR could not read the receipt amount
	transaction_date: string;
	receipt_image_path?: string;
	category_id: string | null;
	categorization_source: 'manual' | 'auto' | null;
	category_name?: string | null;
	category_color?: string | null;
	matched_transaction_id: string | null; // #{#umf1b} - Match status for reconciliation
	currency: string | null; // #{#fcr4a} - Original currency for display
	exchange_rate_to_cad: number | null; // #{#fcr4a} - Bank of Canada rate for estimated CAD
	notes: string | null; // Free-text Note, carried for the row preview only
}

/**
 * The least a row must carry to be matched against a vendor rule: which receipt
 * it is, which merchant it names, and whether it already has a category.
 *
 * `Expense` satisfies this, and so does the Receipts page — which holds
 * `ReceiptRow[]` plus a separate category map rather than `Expense[]`. The rule
 * methods take this instead of a full `Expense` so both list pages can drive the
 * same code, rather than one of them assembling a throwaway `Expense`.

