/**
 * What picking a category on a list row does — extracted so the Expenses and
 * Receipts pages share one description of it rather than two that drift.
 *
 * They already had: the Expenses version persisted immediately, auto-created a
 * vendor rule, applied it to the other visible rows and reported a count, while
 * the Receipts version assigned and created a rule and did neither of the rest,
 * silently. Adding a Category column to Receipts would have put both behaviours
 * on screen at once.
 */

import type { VendorRuleCandidate } from '$lib/services/ExpenseService';
import type { Category } from '$lib/types/Category';

/**
 * The slice of `ExpenseService` this needs. Declared structurally so the tests
 * can drive it without a Supabase mock — `ExpenseService` satisfies it as-is.
 */
export interface CategoryAssignmentPort {
	assignCategory(receiptId: string, categoryId: string, source: 'manual' | 'auto'): Promise<void>;
	bulkAssignCategory(
		receiptIds: string[],
		categoryId: string,
		source: 'manual' | 'auto'
	): Promise<void>;
	getVendorRule(
		familyId: string,
		merchantName: string
	): Promise<{ category_id: string; category_name: string } | null>;
	createVendorRule(familyId: string, merchantName: string, categoryId: string): Promise<void>;
	normalizeVendor(merchantName: string): string;
	applyRuleToVisibleExpenses(
		expenses: VendorRuleCandidate[],
		vendorPattern: string,
		categoryId: string
	): Promise<number>;
}

export interface CategoryAssignmentParams {
	receiptId: string;
	category: Category;
	familyId: string | null;
	/** Rows currently check-selected on the page. */
	selection: ReadonlySet<string>;
	/** Rows currently on screen — the fan-out scope for a newly created rule. */
	visibleRows: VendorRuleCandidate[];
}

/**
 * What happened, in terms the caller can turn into a toast. Deliberately not a
 * message: the two pages word things slightly differently and that is theirs to
 * decide.
 */
export type CategoryAssignment =
	| { kind: 'bulk'; count: number; categoryName: string }
	| {
			kind: 'single';
			categoryName: string;
			ruleCreated: boolean;
			/** Other uncategorized rows the new rule just claimed. */
			autoAppliedCount: number;
	  };

export async function assignCategoryFromRow(
	service: CategoryAssignmentPort,
	{ receiptId, category, familyId, selection, visibleRows }: CategoryAssignmentParams
): Promise<CategoryAssignment> {
	// A pick on a row that is part of a multi-row selection fans out to the whole
	// selection — that is the bulk-recategorize affordance, so there is no
	// separate control. It deliberately does NOT create a vendor rule: the
	// selection spans many merchants, so there is no one merchant to attach to.
	if (selection.has(receiptId) && selection.size > 1) {
		const receiptIds = Array.from(selection);
		await service.bulkAssignCategory(receiptIds, category.id, 'manual');
		return { kind: 'bulk', count: receiptIds.length, categoryName: category.name };
	}

	await service.assignCategory(receiptId, category.id, 'manual');

	// A single checked row falls through to here, so its vendor rule is still
	// auto-created.
	const merchantName = visibleRows.find((row) => row.receipt_id === receiptId)?.merchant_name;
	if (!familyId || !merchantName) {
		return { kind: 'single', categoryName: category.name, ruleCreated: false, autoAppliedCount: 0 };
	}

	// An existing rule is left alone — changing a merchant's default is an
	// explicit act via the dropdown's "change default", not a side effect of
	// categorizing one receipt.
	const existingRule = await service.getVendorRule(familyId, merchantName);
	if (existingRule) {
		return { kind: 'single', categoryName: category.name, ruleCreated: false, autoAppliedCount: 0 };
	}

	await service.createVendorRule(familyId, merchantName, category.id);
	const autoAppliedCount = await service.applyRuleToVisibleExpenses(
		visibleRows,
		service.normalizeVendor(merchantName),
		category.id
	);

	return { kind: 'single', categoryName: category.name, ruleCreated: true, autoAppliedCount };
}

