			header: 'Merchant',
			sortValue: (e) => e.merchant_name,
			cell: merchantCell
		},
		{
			key: 'amount',
			header: 'Amount',
			align: 'right',
			sortValue: (e) => e.total_amount ?? 0,
			cell: amountCell
		},
		{ key: 'category', header: 'Category', interactive: true, cell: categoryCell }
	]}
	getRowId={(e) => e.receipt_id}
	selectable
	bind:selection={expenseSelection}
	onRowClick={openReceiptEditModal}
	initialSort={{ key: 'date', direction: 'desc' }}
	empty={expensesEmpty}
/>

